import Foundation

let generatedHeader = """
    // Generated by swaylib-generate from raylib_api.json. Do not edit by hand.
    // Run `swift run swaylib-generate` after moving the raylib submodule to a new release.

    """

func emitEnums(_ api: API) -> String {
    var out = generatedHeader
    out += "\nimport CRaylib\n"
    for enumeration in api.enums {
        out += "\n"
        if optionSetEnums.contains(enumeration.name) {
            out += emitOptionSet(enumeration)
        } else {
            out += emitEnum(enumeration)
        }
    }
    return out
}

private func emitEnum(_ enumeration: API.Enum) -> String {
    let prefix = commonPrefix(of: enumeration.values.map(\.name))
    var out = docComment(enumeration.description)
    out += "public enum \(enumeration.name): Int32, Sendable, CaseIterable {\n"
    for value in enumeration.values {
        out += docComment(value.description, indent: "    ")
        out += "    case \(swiftCaseName(value.name, prefix: prefix)) = \(value.value)\n"
    }
    out += "}\n"
    return out
}

private func emitOptionSet(_ enumeration: API.Enum) -> String {
    let prefix = commonPrefix(of: enumeration.values.map(\.name))
    var out = docComment(enumeration.description)
    out += "public struct \(enumeration.name): OptionSet, Sendable {\n"
    out += "    /// The raw flag bits, as raylib takes them.\n"
    out += "    public let rawValue: UInt32\n\n"
    out += "    /// Creates a set from raylib's raw flag bits.\n"
    out += "    public init(rawValue: UInt32) {\n        self.rawValue = rawValue\n    }\n"
    for value in enumeration.values {
        out += "\n"
        out += docComment(value.description, indent: "    ")
        let name = swiftCaseName(value.name, prefix: prefix)
        if value.value == 0 {
            out += "    public static let \(name) = \(enumeration.name)([])\n"
        } else {
            out += "    public static let \(name) = \(enumeration.name)(rawValue: \(value.value))\n"
        }
    }
    out += "}\n"
    return out
}

/// Parses wrapped.txt into a map from C function name to Swift symbol.
///
/// One line per wrapped raylib function: the C name, whitespace, then the Swift symbol.
/// Lines starting with `#` are comments.
func parseWrapped(_ text: String, api: API) throws -> [String: String] {
    let known = Set(api.functions.map(\.name))
    var wrapped: [String: String] = [:]
    for (number, rawLine) in text.split(separator: "\n", omittingEmptySubsequences: false).enumerated() {
        let line = rawLine.trimmingCharacters(in: .whitespaces)
        guard !line.isEmpty, !line.hasPrefix("#") else { continue }
        guard let space = line.firstIndex(where: \.isWhitespace) else {
            throw GenerateError("wrapped.txt:\(number + 1): expected '<C function> <Swift symbol>'")
        }
        let cName = String(line[..<space])
        let swift = line[space...].trimmingCharacters(in: .whitespaces)
        guard known.contains(cName) else {
            throw GenerateError("wrapped.txt:\(number + 1): \(cName) is not a raylib function")
        }
        wrapped[cName] = swift
    }
    return wrapped
}

func emitCoverage(_ api: API, wrapped: [String: String], version: String) throws -> String {
    var starts: [String: String] = [:]
    for start in moduleStarts {
        guard api.functions.contains(where: { $0.name == start.firstFunction }) else {
            throw GenerateError("\(start.firstFunction), expected to start \(start.module), is missing")
        }
        starts[start.firstFunction] = start.module
    }

    var sections: [(module: String, functions: [API.Function])] = []
    for function in api.functions {
        if let module = starts[function.name] {
            sections.append((module, []))
        }
        guard !sections.isEmpty else {
            throw GenerateError("\(function.name) comes before the first module")
        }
        sections[sections.count - 1].functions.append(function)
    }

    let total = api.functions.count
    let done = api.functions.filter { wrapped[$0.name] != nil }.count
    var out = """
        # API Coverage

        Which raylib \(version) functions Swaylib wraps, and where.

        ## Overview

        This page is generated by `swift run swaylib-generate` from raylib's `raylib_api.json` and
        `Tools/Generate/wrapped.txt`. \(done) of \(total) functions are wrapped. Functions from
        `raymath.h` and `rlgl.h` are not part of this list.


        """
    for section in sections {
        let count = section.functions.filter { wrapped[$0.name] != nil }.count
        out += "## \(section.module) (\(count) of \(section.functions.count))\n\n"
        out += "| raylib | Swaylib |\n| --- | --- |\n"
        for function in section.functions {
            let swift = wrapped[function.name].map { "``\($0)``" } ?? "not yet"
            out += "| `\(function.name)` | \(swift) |\n"
        }
        out += "\n"
    }
    return out
}

struct GenerateError: Error, CustomStringConvertible {
    var description: String

    init(_ description: String) {
        self.description = description
    }
}
